# watch-openviking.ps1
# Watchdog: if `dsh web` is serving but OpenViking (long-term memory) is not,
# auto-start OpenViking via start-server.bat. Designed to be polled by a
# Windows Scheduled Task (OpenViking-Watchdog) every few minutes.
#
# Behaviour (per request): only act when dsh web is running.
#   - dsh web DOWN                -> do nothing (correct: don't start OV needlessly)
#   - dsh web UP + OV UP          -> healthy, nothing to do
#   - dsh web UP + OV DOWN        -> start OpenViking (guarded against double-launch)

$ErrorActionPreference = 'SilentlyContinue'

$StartBat   = "$env:USERPROFILE\.openviking\start-server.bat"
$DshWebPort = 3080
$OvPort     = 1933
$LogPath    = "$env:USERPROFILE\.openviking\watchdog.log"
$StateFile  = "$env:USERPROFILE\.openviking\watchdog.state"
$CooldownSec = 120   # min seconds between start attempts (covers OV startup time)

function Log($msg) {
    $ts = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
    "$ts  $msg" | Out-File -FilePath $LogPath -Append -Encoding utf8
}

function Test-PortListening($port) {
    return [bool](Get-NetTCPConnection -ErrorAction SilentlyContinue |
        Where-Object { $_.LocalPort -eq $port -and $_.State -eq 'Listen' })
}

function Test-DshWeb {
    if (Test-PortListening $DshWebPort) { return $true }
    # fallback: a node process running `bin.js web`
    return [bool](Get-CimInstance Win32_Process -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -eq 'node.exe' -and $_.CommandLine -match 'bin\.js.*web' })
}

function Test-OvServer {
    if (Test-PortListening $OvPort) { return $true }
    return [bool](Get-CimInstance Win32_Process -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -eq 'openviking-server.exe' -or ($_.CommandLine -match 'openviking-server') })
}

$dshUp = Test-DshWeb
if (-not $dshUp) {
    Log "dsh web not detected (port $DshWebPort down). Skip."
    exit 0
}

$ovUp = Test-OvServer
if ($ovUp) {
    Log "dsh web up; OpenViking healthy (port $OvPort listening). OK."
    exit 0
}

# dsh web up but OpenViking down. Guard against double-launch via cooldown state file.
if (Test-Path $StateFile) {
    $raw = (Get-Content $StateFile -Raw).Trim()
    $last = $null
    if ($raw -and [datetime]::TryParse($raw, [ref]$last)) {
        if (((Get-Date) - $last).TotalSeconds -lt $CooldownSec) {
            Log "OpenViking down but start attempted $([int]((Get-Date)-$last).TotalSeconds)s ago (cooldown $CooldownSec`s). Wait."
            exit 0
        }
    }
}

Log "ACTION: dsh web up but OpenViking down. Launching start-server.bat ..."
try {
    Start-Process -FilePath "cmd.exe" -ArgumentList "/c", "`"$StartBat`"" -WindowStyle Minimized -ErrorAction Stop
    (Get-Date).ToString('o') | Out-File -FilePath $StateFile -Encoding utf8
    Log "ACTION: start-server.bat launched; will re-check next poll."
} catch {
    Log "ERROR launching start-server.bat: $_"
}
exit 0
